function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

const regionNames = {
  northeast: 'Northeastern US',
  southeast: 'Southeastern US',
  midwest:   'Midwestern US',
  west:      'Western US',
  'us-national': 'US National'
};

const stateToRegion = {
  maine:'northeast',massachusetts:'northeast',rhodeisland:'northeast',
  connecticut:'northeast',newhampshire:'northeast',vermont:'northeast',
  newyork:'northeast',newjersey:'northeast',pennsylvania:'northeast',
  maryland:'northeast',delaware:'northeast',
  virginia:'southeast',westvirginia:'southeast',northcarolina:'southeast',
  southcarolina:'southeast',georgia:'southeast',florida:'southeast',
  alabama:'southeast',mississippi:'southeast',tennessee:'southeast',
  kentucky:'southeast',arkansas:'southeast',louisiana:'southeast',
  ohio:'midwest',michigan:'midwest',indiana:'midwest',illinois:'midwest',
  wisconsin:'midwest',minnesota:'midwest',iowa:'midwest',missouri:'midwest',
  northdakota:'midwest',southdakota:'midwest',nebraska:'midwest',kansas:'midwest',
  texas:'west',oklahoma:'west',newmexico:'west',arizona:'west',
  colorado:'west',wyoming:'west',montana:'west',idaho:'west',
  utah:'west',nevada:'west',california:'west',oregon:'west',
  washington:'west',alaska:'west',hawaii:'west'
};

function getRegion(jurisdiction) {
  if (!jurisdiction) return 'us-national';
  const key = jurisdiction.toLowerCase().replace(/\s+/g, '');
  return stateToRegion[key] || 'us-national';
}

const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const row = item.json;

  // ---- WASTEWATER (CDC NWSS API) ----
  if (
    row.wwtp_jurisdiction !== undefined ||
    row.pcr_conc_smoothed !== undefined ||
    row.percentile !== undefined ||
    row.ptc_15d !== undefined
  ) {
    const signal = parseFloat(
      row.pcr_conc_smoothed ?? row.pcr_conc ?? row.percentile ?? 0
    );
    const jurisdiction = row.wwtp_jurisdiction || row.jurisdiction || 'unknown';
    const regionKey = getRegion(jurisdiction);
    const dateEnd = row.date_end || row.date || new Date().toISOString();
    const id = simpleHash('wastewater:' + jurisdiction + ':' + dateEnd);

    results.push({ json: {
      event_id:    id,
      source:      'wastewater',
      signal_key:  'pulsechain-wastewater',
      region:      regionKey,
      region_name: regionNames[regionKey] || jurisdiction,
      signal_value: isNaN(signal) ? 0 : signal,
      unit:        'percentile',
      source_ts:   dateEnd,
      ingested_at: new Date().toISOString()
    }});
    continue;
  }

  // ---- PHARMACY ----
  if (row.source === 'pharmacy' || row.purchase_index !== undefined) {
    const signal = parseFloat(row.purchase_index ?? 0);
    const regionKey = row.region || 'us-national';
    const id = simpleHash('pharmacy:' + regionKey + ':' + (row.timestamp || row.source_ts || Date.now()));

    results.push({ json: {
      event_id:    id,
      source:      'pharmacy',
      signal_key:  'pulsechain-pharmacy',
      region:      regionKey,
      region_name: row.region_name || regionNames[regionKey] || 'US National',
      signal_value: isNaN(signal) ? 0 : signal,
      unit:        'purchase_index',
      source_ts:   row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    continue;
  }

  // ---- SEARCH TRENDS ----
  if (row.source === 'search_trends' || row.search_index !== undefined) {
    const signal = parseFloat(row.search_index ?? row.value ?? 0);
    const regionKey = row.region || 'us-national';
    const id = simpleHash('search_trends:' + regionKey + ':' + (row.timestamp || row.source_ts || Date.now()));

    results.push({ json: {
      event_id:    id,
      source:      'search_trends',
      signal_key:  'pulsechain-search-trends',
      region:      regionKey,
      region_name: row.region_name || regionNames[regionKey] || 'US National',
      signal_value: isNaN(signal) ? 0 : signal,
      unit:        'search_index',
      source_ts:   row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    continue;
  }

  // ---- ABSENTEEISM ----
  if (row.source === 'absenteeism' || row.absenteeism_rate !== undefined) {
    const signal = parseFloat(row.absenteeism_rate ?? row.rate ?? row.index ?? 0);
    const regionKey = row.region || 'us-national';
    const id = simpleHash('absenteeism:' + regionKey + ':' + (row.timestamp || row.source_ts || Date.now()));

    results.push({ json: {
      event_id:    id,
      source:      'absenteeism',
      signal_key:  'pulsechain-absenteeism',
      region:      regionKey,
      region_name: row.region_name || regionNames[regionKey] || 'US National',
      signal_value: isNaN(signal) ? 0 : signal,
      unit:        'absenteeism_rate',
      source_ts:   row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    continue;
  }

  // ---- ED TRIAGE ----
  if (
    row.source === 'ed_triage' ||
    row.triage_index !== undefined ||
    row.visit_index !== undefined
  ) {
    const signal = parseFloat(
      row.triage_index ?? row.visit_index ?? row.severity_score ?? row.index ?? 0
    );
    const regionKey = row.region || 'us-national';
    const id = simpleHash('ed_triage:' + regionKey + ':' + (row.timestamp || row.source_ts || Date.now()));

    results.push({ json: {
      event_id:    id,
      source:      'ed_triage',
      signal_key:  'pulsechain-ed-triage',
      region:      regionKey,
      region_name: row.region_name || regionNames[regionKey] || 'US National',
      signal_value: isNaN(signal) ? 0 : signal,
      unit:        'triage_index',
      source_ts:   row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    continue;
  }

  // ---- NESTED DATA ARRAYS ----
  if (Array.isArray(row.data)) {
    for (const sub of row.data) {
      const src = sub.source || row.source || 'unknown';
      const signal = parseFloat(
        sub.purchase_index ?? sub.search_index ?? sub.absenteeism_rate ??
        sub.triage_index ?? sub.visit_index ?? sub.pcr_conc_smoothed ??
        sub.percentile ?? 0
      );
      const regionKey = sub.region || 'us-national';
      const id = simpleHash(src + ':' + regionKey + ':' + (sub.timestamp || Date.now()));

      results.push({ json: {
        event_id:    id,
        source:      src,
        signal_key:  'pulsechain-' + src.replace(/_/g, '-'),
        region:      regionKey,
        region_name: sub.region_name || regionNames[regionKey] || 'US National',
        signal_value: isNaN(signal) ? 0 : signal,
        unit:        'index',
        source_ts:   sub.timestamp || new Date().toISOString(),
        ingested_at: new Date().toISOString()
      }});
    }
  }
}

console.log('Normalized ' + results.length + ' events from ' + allItems.length + ' raw items');
return results.length > 0 ? results : [{ json: { _empty: true } }];

const results = [];

for (const item of $input.all()) {
  const d = item.json;
  if (d._empty) continue;

  const errors = [];
  if (!d.event_id)                        errors.push('missing event_id');
  if (d.signal_value == null)             errors.push('missing signal_value');
  if (typeof d.signal_value !== 'number') errors.push('signal_value not numeric');
  if (!d.source)                          errors.push('missing source');

  if (d.source === 'wastewater' && (d.signal_value < 0 || d.signal_value > 50000000))
    errors.push('wastewater out of range');

  if (['pharmacy','search_trends','absenteeism','ed_triage'].includes(d.source) &&
      (d.signal_value < 0 || d.signal_value > 1000))
    errors.push('index out of range');

  results.push({
    json: {
      ...d,
      is_valid: errors.length === 0,
      dlq_reason: errors.join('; ')
    }
  });
}

return results;

// Parse Kafka message wrapper
const raw = $input.first().json;
const e = typeof raw.message === 'string' ? JSON.parse(raw.message) : raw;

// Generate stable ID without crypto module
function generateId(source, region, ts) {
  const str = (source || 'unknown') + ':' + (region || 'unknown') + ':' + (ts || Date.now());
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).padStart(8, '0') + 
         '-' + Date.now().toString(16) +
         '-' + Math.random().toString(16).slice(2, 10);
}

const id = e.event_id || generateId(e.source, e.region, e.source_ts);

return [{ json: { ...e, event_id: id, enriched_at: new Date().toISOString() } }];

// ============================================================
// Z-SCORE ANOMALY DETECTOR
// Computes z-score vs historical baseline.
// Falls back to a heuristic threshold if no baseline exists.
// ============================================================
const baselineRows = $input.all();
const baseline = baselineRows.length > 0 && baselineRows[0].json.source ? baselineRows[0].json : null;

// Get event from previous node context
const event = $node["Enrich + Guarantee ID"].json;

let z_score = 0;
let is_anomaly = false;
let detection_method = 'z_score';

if (baseline && baseline.std_dev && parseFloat(baseline.std_dev) > 0) {
  z_score = (event.signal_value - parseFloat(baseline.mean)) / parseFloat(baseline.std_dev);
  is_anomaly = Math.abs(z_score) >= 2.0;
} else {
  detection_method = 'heuristic';
  const thresholds = {
    wastewater:    100000,
    pharmacy:      70,
    search_trends: 65,
    absenteeism:   0.15,
    ed_triage:     60
  };
  const threshold = thresholds[event.source] || 50;
  is_anomaly = event.signal_value > threshold;
  z_score = is_anomaly ? 2.5 : 0;
}

z_score = Math.round(z_score * 100) / 100;

return [{ json: {
  ...event,
  z_score,
  is_anomaly,
  detection_method,
  baseline_mean: baseline ? parseFloat(baseline.mean) : null,
  baseline_std:  baseline ? parseFloat(baseline.std_dev) : null,
  signal_context: {
    [event.source]: {
      value: event.signal_value,
      z_score,
      trust: 1.0,
      freshness: 1.0
    }
  },
  analyzed_at: new Date().toISOString()
}}];

const event = $input.first().json;

const signals = {};
signals[event.source] = {
  z_score:   parseFloat(event.z_score) || 0,
  trust:     1.0,
  freshness: 1.0
};

const payload = {
  region:          event.region,
  region_name:     event.region_name || event.region,
  signals:         signals,
  prior:           0.02,
  observed_values: { [event.source]: parseFloat(event.signal_value) || 0 },
  explain:         true,
  forecast_spread: true,
  horizon_days:    14,
  _upstream:       event
};

return [{ json: payload }];

// ════════════════════════════════════════════════════════════
// PULSECHAIN — Merge & Tier Node (standalone, no fusion API)
// ════════════════════════════════════════════════════════════

// ── 1. Get raw signal from input ─────────────────────────────
const raw = $input.first().json || {};

// Data is nested inside _upstream.metadata — flatten it
const meta = raw._upstream?.metadata || {};
const up   = raw._upstream || {};

const region       = meta.region       || raw.region       || 'unknown';
const region_name  = meta.region_name  || raw.region_name  || region;
const z_score      = meta.z_score      ?? raw.z_score      ?? 0;
const source       = up.signal_type    || raw.source       || 'unknown';
const signal_value = up.signal_value   || raw.signal_value || null;
const event_id     = up.id             || raw.event_id     || ('evt_' + Date.now());
const prior        = raw.prior         || 0.02;

// ── 2. Compute posterior from z_score ────────────────────────
const z = parseFloat(z_score) || 0;
let posterior;

if      (z >= 4.0) posterior = 0.99;
else if (z >= 3.0) posterior = 0.75 + (z - 3.0) * 0.24;
else if (z >= 2.0) posterior = 0.50 + (z - 2.0) * 0.25;
else if (z >= 1.5) posterior = 0.25 + (z - 1.5) * 0.50;
else if (z >= 1.0) posterior = 0.10 + (z - 1.0) * 0.30;
else               posterior = Math.max(0, z * 0.10);

posterior = Math.min(0.99, Math.max(0, posterior));

// ── 3. Alert tier ─────────────────────────────────────────────
const alert_tier = posterior >= 0.75 ? 1
                 : posterior >= 0.50 ? 2
                 : posterior >= 0.25 ? 3
                 : 0;

const tierLabels = { 0:'NORMAL', 1:'EMERGENCY', 2:'ADVISORY', 3:'WATCH' };

// ── 4. Build output ───────────────────────────────────────────
const merged = {
  event_id,
  region,
  region_name,
  source,
  signal_value,
  z_score,
  posterior_probability: posterior,
  credible_interval:     null,
  confidence:            posterior > 0.75 ? 0.9 : posterior > 0.5 ? 0.8 : 0.6,
  dominant_signal:       source,
  alert_tier,
  tier_label:            tierLabels[alert_tier],
  drivers:               [],
  recommended_actions:   alert_tier === 1 ? ['Notify health authority immediately','Activate emergency protocol','Dispatch field team','Issue public advisory']
                       : alert_tier === 2 ? ['Notify regional health dept (2h)','Increase ED surveillance','Alert hospitals']
                       : alert_tier === 3 ? ['Enhanced monitoring','Cross-verify with lab data','Review in 24h']
                       : ['Continue routine monitoring'],
  explanation_summary:   `${source} anomaly detected in ${region_name} (z=${Number(z_score).toFixed(2)})`,
  explanation_markdown:  '',
  spread_forecast:       null,
  lead_time_estimate:    '3-7 days',
  log_odds_ratio:        null,
  bayesian_method:       'z_score_heuristic',
  fusion_source:         'merge_node',
  pipeline_version:      '3.0',
  assessed_at:           new Date().toISOString(),
  workflow_execution_id: $execution?.id || null,
};

console.log(`[PulseChain] region=${region} | source=${source} | z=${z_score} | posterior=${(posterior*100).toFixed(1)}% | tier=${alert_tier} (${tierLabels[alert_tier]})`);

return [{ json: merged }];

// ============================================================
// ALERT TIER NORMALIZER (inline — no sub-workflow needed)
// ============================================================
const d = $input.first().json;

let tier = d.alert_tier;
if (tier === undefined) {
  if (d.severity === 'critical') tier = 1;
  else if (d.severity === 'warning') tier = 2;
  else if (d.severity === 'watch') tier = 3;
  else {
    const score = d.posterior_probability || d.risk_score || 0;
    tier = score >= 0.75 ? 1 : score >= 0.50 ? 2 : score >= 0.25 ? 3 : 0;
  }
}

const tierLabels = { 1: 'EMERGENCY', 2: 'ADVISORY', 3: 'WATCH', 0: 'NORMAL' };

console.log('Routing tier ' + tier + ' (' + tierLabels[tier] + ') for ' + (d.region_name || d.region));

return [{ json: {
  ...d,
  alert_tier:  tier,
  tier_label:  tierLabels[tier] || 'UNKNOWN',
  routed_at:   new Date().toISOString()
}}];

const d = $input.first().json;
console.log(' Normal — no alert for ' + (d.region_name || d.region));
return [{ json: {
  ...d,
  notification_channel: 'none',
  notification_sent_at: new Date().toISOString(),
  actually_notified: false
}}];

const d = $input.first().json;

console.log(' TIER 2 ADVISORY ALERT');
console.log('Region:', d.region_name);
console.log('Score:', (d.posterior_probability * 100).toFixed(1) + '%');

const message = [
  ' PULSECHAIN — TIER 2 ADVISORY',
  '=================================',
  'Region:       ' + d.region_name,
  'Risk Score:   ' + (d.posterior_probability * 100).toFixed(1) + '%',
  'Confidence:   ' + (d.confidence * 100).toFixed(0) + '%',
  '',
  'Summary: ' + d.explanation_summary,
  '',
  'Actions:',
  ...(d.recommended_actions || ['Monitor situation closely', 'Prepare response resources', 'Brief health officials']).map(a => '  • ' + a),
  '',
  'Assessment ID: ' + d.event_id
].join('\n');

return [{ json: {
  ...d,
  notification_channel: 'tier2_advisory',
  notification_message: message,
  notification_sent_at: new Date().toISOString(),
  actually_notified: false
}}];

const d = $input.first().json;
console.log(' TIER 3 WATCH MODE — ' + d.region_name);
return [{ json: {
  ...d,
  notification_channel: 'tier3_watch',
  notification_message: ' WATCH: ' + d.region_name + ' | Score: ' + (d.posterior_probability*100).toFixed(1) + '%',
  notification_sent_at: new Date().toISOString(),
  actually_notified: false
}}];

// ============================================================
// DISPATCH RECORDER + AUDIT TRAIL
// Creates an immutable dispatch record for every alert.
// In production: INSERT into alert_dispatches table.
// Also triggers the audit logger inline.
// ============================================================
const d = $input.first().json;

// Generate ID without crypto
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).padStart(8, '0');
}

const dispatch_id = 'dsp_' + d.event_id + '_' + (d.notification_channel || 'system') + '_' + Date.now();

const dispatchRecord = {
  dispatch_id:      dispatch_id,
  assessment_id:    d.event_id,
  alert_tier:       d.alert_tier,
  tier_label:       d.tier_label,
  region:           d.region,
  region_name:      d.region_name,
  channel:          d.notification_channel,
  status:           d.actually_notified ? 'sent' : 'logged_only',
  message_preview:  (d.notification_message || '').substring(0, 200),
  sent_at:          d.notification_sent_at,
  recorded_at:      new Date().toISOString()
};

// Build audit log entry without crypto
const auditHashInput = (d.event_id || '') + (d.notification_sent_at || new Date().toISOString());
const auditHash = simpleHash(auditHashInput) + simpleHash(auditHashInput.split('').reverse().join(''));

const auditEntry = {
  log_id:         auditHash,
  workflow_id:    'pulsechain_unified_v3',
  execution_id:   $execution.id || 'unknown',
  node_name:      'dispatch_recorder',
  action:         'tier_routed_and_dispatched',
  decision_tier:  d.alert_tier,
  operator_id:    'system',
  metadata: JSON.stringify({
    tier:              d.alert_tier,
    tier_label:        d.tier_label,
    region:            d.region,
    region_name:       d.region_name,
    posterior:         d.posterior_probability,
    confidence:        d.confidence,
    dominant_signal:   d.dominant_signal,
    fusion_source:     d.fusion_source,
    dispatch_id:       dispatch_id,
    channel:           d.notification_channel,
    actually_notified: d.actually_notified
  }),
  logged_at: new Date().toISOString()
};

console.log('=== DISPATCH RECORD ===');
console.log(JSON.stringify(dispatchRecord, null, 2));
console.log('=== AUDIT ENTRY ===');
console.log(JSON.stringify(auditEntry, null, 2));

return [{ json: { dispatch: dispatchRecord, audit: auditEntry, ...d, dispatch_id } }];

const items = $input.all();
const count = items.filter(i => !i.json._empty).length;
console.log('SLA check: ' + count + ' dispatches pending acknowledgment');
return [{ json: { count, checked_at: new Date().toISOString() } }];

// ============================================================
// ERROR CLASSIFIER
// Categorizes errors by severity and decides paging + retry.
// ============================================================
const e = $input.first().json || {};
const msg = e.error?.message || 'Unknown error';
let severity = 'warning';
let page = false;
let retry = true;

if (['NodeConnectionError','NetworkError'].includes(e.error?.name)) {
  severity = 'error';
} else if (e.error?.name === 'AuthenticationError') {
  severity = 'critical';
  page = true;
  retry = false;
} else if (msg.toLowerCase().includes('kafka') || msg.toLowerCase().includes('postgres')) {
  severity = 'critical';
  page = true;
}

console.error('PulseChain Error | ' + severity + ' | ' + msg);

return [{ json: {
  error_id:       'err_' + Date.now() + '_' + Math.random().toString(36).slice(2,8),
  workflow_name:  e.workflow?.name || 'pulsechain_unified_v3',
  execution_id:   e.execution?.id || $execution.id,
  error_type:     e.error?.name || 'Error',
  error_message:  msg,
  severity,
  should_page:    page,
  should_retry:   retry,
  occurred_at:    new Date().toISOString(),
  raw_error:      JSON.stringify(e)
}}];
